class Solution:
    def validIPAddress(self, queryIP: str) -> str:
        if '.' in queryIP:
            parts = queryIP.split('.')
            if len(parts) != 4:
                return "Neither"
            for part in parts:
                if not part or not part.isdigit() or (len(part) > 1 and part[0] == '0') or int(part) > 255:
                    return "Neither"
            return "IPv4"
        if ':' in queryIP:
            parts = queryIP.split(':')
            if len(parts) != 8:
                return "Neither"
            hex_chars = set('0123456789abcdefABCDEF')
            for part in parts:
                if not part or len(part) > 4 or not all(c in hex_chars for c in part):
                    return "Neither"
            return "IPv6"
        return "Neither"

